import { db } from "@/db"; import { vendors } from "@/db/schema"; import { desc, ilike, or } from "drizzle-orm"; import { getCurrentUser, unauthorized, err, ok } from "@/lib/auth"; import { forbid } from "@/lib/rbac";
export async function GET(req:Request){ const u=await getCurrentUser(); if(!u) return unauthorized(); const s=new URL(req.url).searchParams.get("search")||""; const rows=await db.select().from(vendors).where(s?or(ilike(vendors.name,`%${s}%`),ilike(vendors.email,`%${s}%`)):undefined).orderBy(desc(vendors.createdAt)); return ok({items:rows,total:rows.length}); }
export async function POST(req:Request){ const u=await getCurrentUser(); if(!u) return unauthorized(); const f=forbid(u,"vendor.write"); if(f) return f; const b=await req.json(); if(!b.name) return err("Vendor name required"); const [r]=await db.insert(vendors).values({name:b.name,email:b.email||null,phone:b.phone||null,category:b.category||null,address:b.address||null,city:b.city||null,country:b.country||null,status:b.status||"active",notes:b.notes||null}).returning(); return ok(r,201); }
